1	/**
2	 * Screen 05 projection tests for the TUNNEL (2026-11-16, qa/pilot05/proj/tunnel/NOTES.md), same method as the water
3	 * (`?proj05=1`): the user's APPROVED Screen 05 picture, unwrapped into the tunnel's own coordinates and baked into
4	 * textures (tools/proj05/tunnel_rings.py + tunnel_bake.py → assets/textures/tunnel05/), so the design is anchored to the
5	 * 3D tunnel, not pasted over the screen.
6	 *   `?projwall05=1`  the purple metal WALLS: one texture row per wall bay between two gold rings (AB, BC, CD … as the
7	 *                    approved picture shows them from the locked 05 camera); u = angle round the tube, v = depth within
8	 *                    the bay. Bays the picture does not show (in front of ring A, behind the camera) repeat the AB row.
9	 *   `?projring05=1`  the gold RINGS: the band of the approved ring B unwrapped (u = angle round the ring, v = how far the
10	 *                    band stands out of the wall), on every 05 ring; the existing far glow still melts the far rings
11	 *                    into the warm throat.
12	 * The shader undoes the post chain (grade → sRGB → Neutral tone map → exposure) so the screen shows the approved
13	 * colours; bloom is measured and fed back into the bake. Default build: none of this runs — the wall and ring
14	 * materials are wrapped only when a switch is on, every default shader program is unchanged.
15	 */
16	import * as THREE from 'three';
17	import { PROJ05_INVERSE, on05, proj05Pending } from './waterRibbon';
18	// the tunnel bake follows its own switches OR the master `?match05=1` (on05)
19	const flag05 = on05;
20	import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
21	
22	export const PROJWALL05: boolean = flag05('projwall05');
23	export const PROJRING05: boolean = flag05('projring05');
24	/** `?projframe05=1` (2026-11-16): the near gold frame (bottom corners + bottom lip) wears the approved gold band */
25	export const PROJFRAME05: boolean = flag05('projframe05');
26	/** `?projlid05=1` (2026-11-16): the approved paddles L1 L2 R1 R2 as Blender-built 3D trays on the real 05 wall */
27	export const PROJLID05: boolean = flag05('projlid05');
28	/**
29	 * `?env05=1` (2026-11-17, washer-environment-modeler, qa/pilot05/full_reference_match/env/NOTES.md): the 05 rings placed
30	 * where the approved picture shows them from the locked camera (src/world/environment.ts) and the walls / rings baked by
31	 * CAMERA PROJECTION in their own coordinates (tools/env05/proj_bake.py → assets/textures/env05/): wall atlas with own
32	 * rows for the near bays (N1, N2), and one ring atlas row per ring (A, B, C … G, N) sampled by (angle round the ring,
33	 * axial position across the band). Off = every program and texture exactly as before.
34	 */
35	export const ENV05: boolean = flag05('env05');
36	
37	/**
38	 * The approved paddle is a D-shaped TRAY (studied at 4× zoom: a thick polished gold rim whose INNER face shows above a
39	 * lavender floor, a thin straight lip along the bottom). Half lathe toward local +X like wallLidGeometry: the D's
40	 * straight edge lies on local Z (along the tube); the open side faces −Y (the camera / the stream), the closed back +Y
41	 * (into the wall). Thickness h = tray depth (fraction of the size), centred on its thickness like the wall lids.
42	 */
43	export function trayLidGeometry(h: number, segments = 28): THREE.BufferGeometry {
44	  const prof: [number, number][] = [
45	    [0, 0.68 * h], [0.78, 0.68 * h], [0.84, 0.62 * h],         // floor (recessed from the open side), fillet
46	    [0.855, 0.3 * h], [0.865, 0.06 * h], [0.9, 0.0],            // inner rim face down to the lip
47	    [0.965, 0.0], [1.0, 0.06 * h], [1.025, 0.4 * h],            // rounded lip, outer bulge
48	    [1.0, 0.85 * h], [0.95, h], [0, h],                          // closed back against the wall
49	  ];
50	  const geo = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), segments, 0, Math.PI);
51	  geo.translate(0, -h * 0.5, 0);
52	  return geo;
53	}
54	
55	/**
56	 * `?projlid05=1` (Blender pipeline, qa/pilot05/proj/tunnel/NOTES.md): the approved picture's four large paddles L1 L2 R1
57	 * R2 (+ the small far pair L3 R3 on the far wall) as real 3D tray-blocks on the real 05 wall (assets/models/lids05.glb, built in Blender by tools/proj05/lid_blender.py
58	 * from the approved outlines lifted onto the wall through the locked 05 camera). From the checkpoint their outline is the
59	 * approved one; riding on, they show their real depth. They carry the approved paddle pixels (camera-projected UVs,
60	 * assets/textures/tunnel05/lid05.png inside the GLB), shown through the post-chain inverse like the walls. The default
61	 * paddle pairs and the far slab pucks are left out under the switch.
62	 */
63	let lids05Scene: THREE.Object3D | null = null;
64	const lids05Ready: Promise<void> | null = PROJLID05
65	  ? new GLTFLoader().loadAsync(new URL('../../assets/models/lids05.glb', import.meta.url).href).then((gltf) => {
66	    gltf.scene.traverse((o) => {
67	      const m = o as THREE.Mesh;
68	      if (!m.isMesh) return;
69	      const map = (m.material as THREE.MeshStandardMaterial).map;
70	      if (!map) return;
71	      map.colorSpace = THREE.NoColorSpace;          // the texels ARE display values: the shader undoes the post chain
72	      map.needsUpdate = true;
73	      m.material = lidProjMaterial(map);
74	      m.frustumCulled = false;
75	    });
76	    lids05Scene = gltf.scene;
77	    lids05Scene.name = 'tube05_lids_blender';
78	  }).catch((e) => { console.error('[rainbow] projlid05: lids05.glb failed', e); })
79	  : null;
80	if (lids05Ready) proj05Pending.push(lids05Ready);
81	
82	function lidProjMaterial(map: THREE.Texture): THREE.MeshBasicMaterial {
83	  const mat = new THREE.MeshBasicMaterial({ map, side: THREE.DoubleSide, fog: false });
84	  mat.onBeforeCompile = (shader) => {
85	    Object.assign(shader.uniforms, shared);
86	    shader.fragmentShader = shader.fragmentShader
87	      .replace('void main() {', `uniform vec4 uPjPost; uniform vec2 uPjRes;
88	${PROJ05_INVERSE}
89	void main() {`)
90	      .replace('#include <dithering_fragment>', `#include <dithering_fragment>
91	gl_FragColor = vec4(pjInverse(texture2D(map, vMapUv).rgb), 1.0);   // ?projlid05=1: the approved paddle pixels`);
92	  };
93	  mat.customProgramCacheKey = () => 'ptlid05';
94	  mat.onBeforeRender = (renderer) => livePost(renderer);
95	  return mat;
96	}
97	
98	/** the group environment.ts adds under `?projlid05=1`; the Blender paddles join it once the GLB has loaded */
99	export function lids05Group(): THREE.Group {
100	  const g = new THREE.Group();
101	  g.name = 'tube05_lids05';
102	  const attach = () => { if (lids05Scene) g.add(lids05Scene); };
103	  if (lids05Scene) attach(); else lids05Ready?.then(attach);
104	  return g;
105	}
106	
107	/** atlas rows of wall05.png (tools/proj05/tunnel_bake.py: ROWS) */
108	export const PT_ROW = { AB: 0, BC: 1, CD: 2, DE: 3, EF: 4, FG: 5, GX: 6, N1: 7, N2: 8 } as const;
109	const N_ROWS = ENV05 ? 9 : 7;
110	/** `?env05=1` ring atlas rows (assets/textures/env05/env05.json: ring.rows) */
111	export const E5_RING_ROW = { A: 0, B: 1, C: 2, D: 3, E: 4, F: 5, G: 6, N: 7 } as const;
112	const N_SEG = 8;
113	
114	const empty = new THREE.DataTexture(new Uint8Array([128, 40, 150, 255]), 1, 1);
115	empty.needsUpdate = true;
116	
117	const shared = {
118	  uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) },
119	  uPjRes: { value: new THREE.Vector2(864, 1536) },
120	  uPtWall: { value: empty as THREE.Texture },
121	  uPtWallSize: { value: new THREE.Vector2(1, 1) },
122	  uPtRows: { value: Array.from({ length: N_ROWS }, () => new THREE.Vector2(0, 1)) },
123	  uPtRing: { value: empty as THREE.Texture },
124	  uPtRingSize: { value: new THREE.Vector2(1, 1) },
125	  uPtFrame: { value: empty as THREE.Texture },
126	  /** frame05.png: (texture height, band rows NV, left y0, right y0); lip y0 in uPtFrameLip */
127	  uPtFrameRows: { value: new THREE.Vector4(1, 1, 0, 0) },
128	  uPtFrameLip: { value: 0 },
129	  /** `?env05=1`: ring atlas, (texture height, rows height) */
130	  uE5Ring: { value: empty as THREE.Texture },
131	  uE5RingSize: { value: new THREE.Vector3(1, 1, 1) },
132	  /** QA only (scripts/proj05-tunnel-probe.mjs --coords): 1 = write the texture coordinates instead of the colour */
133	  uPtDbg: { value: 0 },
134	};
135	/** QA accessor for the probe script */
136	export const proj05TunnelShared = shared;
137	
138	function loadTextures() {
139	  const loader = new THREE.TextureLoader();
140	  const load = (url: string) =>
141	    new Promise<THREE.Texture>((res, rej) =>
142	      loader.load(url, (t) => {
143	        t.flipY = false;
144	        t.colorSpace = THREE.NoColorSpace;          // the texels ARE display values: the shader undoes the post chain
145	        t.generateMipmaps = false;
146	        t.minFilter = THREE.LinearFilter;
147	        t.magFilter = THREE.LinearFilter;
148	        t.wrapS = THREE.RepeatWrapping;             // round the tube
149	        t.wrapT = THREE.ClampToEdgeWrapping;
150	        t.needsUpdate = true;
151	        res(t);
152	      }, undefined, rej));
153	  const jobs: Promise<unknown>[] = [];
154	  if (PROJWALL05 || ENV05) {
155	    jobs.push(Promise.all([
156	      load(ENV05 ? new URL('../../assets/textures/env05/wall05e.png', import.meta.url).href : new URL('../../assets/textures/tunnel05/wall05.png', import.meta.url).href),
157	      fetch(ENV05 ? new URL('../../assets/textures/env05/env05.json', import.meta.url).href : new URL('../../assets/textures/tunnel05/tunnel05.json', import.meta.url).href).then((r) => r.json()),
158	    ]).then(([t, meta]) => {
159	      shared.uPtWall.value = t;
160	      shared.uPtWallSize.value.set(meta.wall.w, meta.wall.h);
161	      (Object.keys(PT_ROW) as (keyof typeof PT_ROW)[]).forEach((k) => {
162	        const r = meta.wall.rows[k];
163	        if (r) shared.uPtRows.value[PT_ROW[k]].set(r.y0, r.h);
164	      });
165	    }));
166	  }
167	  if (ENV05) {
168	    jobs.push(Promise.all([
169	      load(new URL('../../assets/textures/env05/ring05e.png', import.meta.url).href),
170	      fetch(new URL('../../assets/textures/env05/env05.json', import.meta.url).href).then((r) => r.json()),
171	    ]).then(([t, meta]) => {
172	      shared.uE5Ring.value = t;
173	      shared.uE5RingSize.value.set(meta.ring.w, meta.ring.h, meta.ring.rowH);
174	    }));
175	  }
176	  if (PROJRING05) {
177	    jobs.push(load(new URL('../../assets/textures/tunnel05/ring05.png', import.meta.url).href).then((t) => {
178	      shared.uPtRing.value = t;
179	      shared.uPtRingSize.value.set(t.image.width, t.image.height);
180	    }));
181	  }
182	  if (PROJFRAME05) {
183	    jobs.push(Promise.all([
184	      load(new URL('../../assets/textures/tunnel05/frame05.png', import.meta.url).href),
185	      fetch(new URL('../../assets/textures/tunnel05/frame05.json', import.meta.url).href).then((r) => r.json()),
186	    ]).then(([t, meta]) => {
187	      t.wrapS = THREE.ClampToEdgeWrapping;          // the frame bands are open arcs, not closed rings
188	      t.needsUpdate = true;
189	      shared.uPtFrame.value = t;
190	      shared.uPtFrameRows.value.set(meta.h, meta.rows.left.h, meta.rows.left.y0, meta.rows.right.y0);
191	      shared.uPtFrameLip.value = meta.rows.lip.y0;
192	    }));
193	  }
194	  return Promise.all(jobs).catch((e) => { console.error('[rainbow] proj05 tunnel textures failed', e); });
195	}
196	// the game waits for these before `ready` (vfx/index.ts), so a capture never shows the 1×1 placeholder
197	if (PROJWALL05 || PROJRING05 || PROJFRAME05 || ENV05) proj05Pending.push(loadTextures());
198	
199	const size = new THREE.Vector2();
200	function livePost(renderer: THREE.WebGLRenderer) {
201	  const rt = renderer.getRenderTarget();
202	  if (rt) size.set(rt.width, rt.height); else renderer.getDrawingBufferSize(size);
203	  shared.uPjRes.value.copy(size);
204	  shared.uPjPost.value.x = renderer.toneMappingExposure;
205	}
206	
207	/** one wall bay: tunnel coordinate range [v0, v1) (the wall's uv.y) → atlas row, t at v0 and at v1 */
208	export interface WallSeg { v0: number; v1: number; row: number; t0: number; t1: number }
209	
210	/**
211	 * `?projwall05=1`: wrap a perforatedMetal wall material (real 05 wall or the forced-perspective far wall; both carry
212	 * `vPerfUv` = (angle round the tube 0..1 from the top, tunnel coordinate)). `segs` (≤ 8) lists the bays; anything outside
213	 * them repeats the AB row every `tile.period` units from `tile.anchor`.
214	 */
215	export function withProj05Wall<T extends THREE.MeshStandardMaterial>(mat: T, segs: WallSeg[], tile: { anchor: number; period: number }, key: string): T {
216	  const seg = Array.from({ length: N_SEG }, (_, i) => (segs[i] ? new THREE.Vector4(segs[i].v0, segs[i].v1, 0, 0) : new THREE.Vector4(1e9, 1e9, 0, 0)));
217	  const segT = Array.from({ length: N_SEG }, (_, i) => (segs[i] ? new THREE.Vector3(segs[i].row, segs[i].t0, segs[i].t1) : new THREE.Vector3(0, 0, 0)));
218	  const uniforms = { ...shared, uPtSeg: { value: seg }, uPtSegT: { value: segT }, uPtTile: { value: new THREE.Vector2(tile.anchor, tile.period) } };
219	  const prev = mat.onBeforeCompile;
220	  mat.onBeforeCompile = (shader, r) => {
221	    prev.call(mat, shader, r);
222	    Object.assign(shader.uniforms, uniforms);
223	    shader.fragmentShader = shader.fragmentShader
224	      .replace('void main() {', `uniform sampler2D uPtWall; uniform vec2 uPtWallSize; uniform vec2 uPtRows[${N_ROWS}];
225	uniform vec4 uPtSeg[${N_SEG}]; uniform vec3 uPtSegT[${N_SEG}]; uniform vec2 uPtTile; uniform float uPtDbg;
226	uniform vec4 uPjPost; uniform vec2 uPjRes;
227	${PROJ05_INVERSE}
228	void main() {`)
229	      .replace('#include <dithering_fragment>', `#include <dithering_fragment>
230	{ // ?projwall05=1: the approved wall of this bay (texture anchored to the tunnel)
231	  float pv = vPerfUv.y;
232	  float prow = 0.0;
233	  float pt = fract((pv - uPtTile.x) / uPtTile.y);
234	  for (int i = 0; i < ${N_SEG}; i++) {
235	    vec4 sg = uPtSeg[i];
236	    if (pv >= sg.x && pv < sg.y) { prow = uPtSegT[i].x; pt = mix(uPtSegT[i].y, uPtSegT[i].z, (pv - sg.x) / (sg.y - sg.x)); }
237	  }
238	  vec2 rw = uPtRows[int(prow + 0.5)];
239	  vec2 puv = vec2(fract(vPerfUv.x + 0.25), (rw.x + clamp(pt * rw.y, 0.5, rw.y - 0.5)) / uPtWallSize.y);
240	  vec3 pc = texture2D(uPtWall, puv).rgb;
241	  gl_FragColor = uPtDbg > 0.5 ? vec4(puv, 7.0, 77.0) : vec4(pjInverse(pc), 1.0);
242	}`);
243	  };
244	  const prevKey = mat.customProgramCacheKey.bind(mat);
245	  mat.customProgramCacheKey = () => prevKey() + '|ptwall-' + key;
246	  const prevRender = mat.onBeforeRender;
247	  mat.onBeforeRender = (renderer, ...rest) => { livePost(renderer); prevRender.call(mat, renderer, ...rest); };
248	  return mat;
249	}
250	
251	/**
252	 * `?projring05=1`: wrap a withBandShading ring material. `flip` = the ring's local x points to screen LEFT (the real 05
253	 * rings, basis (−right, up, tan)); the forced-perspective far rings use (right, up, tan). `height` = the band's height
254	 * (BandOpts.height, fraction of the ring radius): v = how far the surface stands out of the wall, 0 wall … 1 crown.
255	 */
256	export function withProj05Ring<T extends THREE.MeshStandardMaterial>(mat: T, flip: boolean, height: number, key: string): T {
257	  const uniforms = { ...shared, uPtRingP: { value: new THREE.Vector2(flip ? 1 : 0, height) } };
258	  const prev = mat.onBeforeCompile;
259	  mat.onBeforeCompile = (shader, r) => {
260	    prev.call(mat, shader, r);
261	    Object.assign(shader.uniforms, uniforms);
262	    const marker = 'vec3 bc = bandShade(smoothstep(uBandF.x, uBandF.y, bDist), normalize(normal), normalize(vViewPosition));';
263	    if (!shader.fragmentShader.includes(marker)) { console.error('[rainbow] projring05: band shader marker not found'); return; }
264	    shader.fragmentShader = shader.fragmentShader
265	      .replace('void main() {', `uniform sampler2D uPtRing; uniform vec2 uPtRingSize; uniform vec2 uPtRingP; uniform float uPtDbg;
266	uniform vec4 uPjPost; uniform vec2 uPjRes;
267	vec2 gPtRingUv;
268	${PROJ05_INVERSE}
269	void main() {`)
270	      .replace(marker, `${marker}
271	  { // ?projring05=1: the approved gold band (ring B of the approved picture), anchored to the ring
272	    float ph = atan(vBandP.y, vBandP.x);
273	    float th = uPtRingP.x > 0.5 ? 3.14159265 - ph : ph;
274	    float rv = clamp((1.0 - length(vBandP.xy)) / uPtRingP.y, 0.0, 1.0);
275	    gPtRingUv = vec2(fract(th / 6.2831853), (0.5 + rv * (uPtRingSize.y - 1.0)) / uPtRingSize.y);
276	    bc = pjInverse(texture2D(uPtRing, gPtRingUv).rgb);
277	  }`)
278	      .replace('#include <dithering_fragment>', `#include <dithering_fragment>
279	if (uPtDbg > 0.5) gl_FragColor = vec4(gPtRingUv, 8.0, 78.0);`);
280	  };
281	  const prevKey = mat.customProgramCacheKey.bind(mat);
282	  mat.customProgramCacheKey = () => prevKey() + '|ptring-' + key;
283	  const prevRender = mat.onBeforeRender;
284	  mat.onBeforeRender = (renderer, ...rest) => { livePost(renderer); prevRender.call(mat, renderer, ...rest); };
285	  return mat;
286	}
287	
288	/**
289	 * `?env05=1`: wrap a withBandShading ring material (real 05 ring: one mesh per ring, `perInstance` false; far rings: one
290	 * instanced mesh, row = row0 + instance index). The colour is the ring's own row of the env05 ring atlas, sampled by
291	 * u = angle round the ring (object space, atan(y, x)), v = axial position across the band (−w camera side … +w far side,
292	 * w = (width + groove + lipWidth) / 2) — unique on the visible band, so the camera-projection bake is exact. Written as the
293	 * final colour through the post-chain inverse (no far-glow / fog on top: the bake already carries the approved look).
294	 */
295	export function withEnv05Ring<T extends THREE.MeshStandardMaterial>(mat: T, row0: number, perInstance: boolean, halfW: number, key: string): T {
296	  const uniforms = { ...shared, uE5RingP: { value: new THREE.Vector2(row0, halfW) } };
297	  const prev = mat.onBeforeCompile;
298	  mat.onBeforeCompile = (shader, r) => {
299	    prev.call(mat, shader, r);
300	    Object.assign(shader.uniforms, uniforms);
301	    const vMark = 'vBandP = position;';
302	    if (!shader.vertexShader.includes(vMark) || !shader.fragmentShader.includes('varying vec3 vBandP;')) { console.error('[rainbow] env05: band shader marker not found'); return; }
303	    shader.vertexShader = shader.vertexShader
304	      .replace('void main() {', 'varying float vE5Inst;\nvoid main() {')
305	      .replace(vMark, `${vMark}
306	#ifdef USE_INSTANCING
307	vE5Inst = ${perInstance ? 'float(gl_InstanceID)' : '0.0'};
308	#else
309	vE5Inst = 0.0;
310	#endif`);
311	    shader.fragmentShader = shader.fragmentShader
312	      .replace('void main() {', `uniform sampler2D uE5Ring; uniform vec3 uE5RingSize; uniform vec2 uE5RingP; uniform float uPtDbg;
313	uniform vec4 uPjPost; uniform vec2 uPjRes;
314	varying float vE5Inst;
315	${PROJ05_INVERSE}
316	void main() {`)
317	      .replace('#include <dithering_fragment>', `#include <dithering_fragment>
318	{ // ?env05=1: this ring's row of the camera-projection ring atlas
319	  float e5row = floor(uE5RingP.x + vE5Inst + 0.5);
320	  float e5v = clamp((vBandP.z + uE5RingP.y) / (2.0 * uE5RingP.y), 0.0, 1.0);
321	  vec2 e5uv = vec2(fract(atan(vBandP.y, vBandP.x) / 6.2831853 + 1.0), (e5row * uE5RingSize.z + 0.5 + e5v * (uE5RingSize.z - 1.0)) / uE5RingSize.y);
322	  gl_FragColor = uPtDbg > 0.5 ? vec4(e5uv, 8.0, 78.0) : vec4(pjInverse(texture2D(uE5Ring, e5uv).rgb), 1.0);
323	}`);
324	  };
325	  const prevKey = mat.customProgramCacheKey.bind(mat);
326	  mat.customProgramCacheKey = () => prevKey() + '|e5ring-' + key;
327	  const prevRender = mat.onBeforeRender;
328	  mat.onBeforeRender = (renderer, ...rest) => { livePost(renderer); prevRender.call(mat, renderer, ...rest); };
329	  return mat;
330	}
331	
332	/**
333	 * `?projframe05=1`: wrap nearFrameMaterial (src/world/materials.ts; geometry nearFrameGeometry in tube.ts). The frame
334	 * is the existing camera-held 3D band (bottom corners + bottom lip); this only replaces its hand-picked palette with the
335	 * approved gold band profile (tools/proj05/frame_bake.py: the approved picture sampled in the frame's own band
336	 * coordinates, hidden parts filled, smoothed along the arc), shown through the post-chain inverse like the walls/rings.
337	 * Which corner: the sign of the geometry's x (reference pixels from the frame centre).
338	 */
339	export function withProj05Frame<T extends THREE.MeshStandardMaterial>(mat: T): T {
340	  /** tan(fov/2) / 768: reference px of depth → relative scale (environment.ts places the frame at depth d = 0.8) */
341	  const frameK = { value: 0 };
342	  const prev = mat.onBeforeCompile;
343	  mat.onBeforeCompile = (shader, r) => {
344	    prev.call(mat, shader, r);
345	    Object.assign(shader.uniforms, shared);
346	    const vMark = 'vFrUv = uv; vFrPiece = framePiece;';
347	    const fMark = '#include <dithering_fragment>';
348	    if (!shader.vertexShader.includes(vMark) || !shader.fragmentShader.includes(fMark)) {
349	      console.error('[rainbow] projframe05: near-frame shader marker not found');
350	      return;
351	    }
352	    // The frame stands toward the viewer (corner z0 40 + half-round bulge, reference px), so perspective pushed its
353	    // outline ≈15–35 px outward from the measured reference edges. Pre-shrink x, y by the depth factor so every
354	    // vertex projects onto its designed reference pixel (the band keeps its 3D bulge for the shading).
355	    shader.uniforms.uPtFrameK = frameK;
356	    shader.vertexShader = shader.vertexShader
357	      .replace('void main() {', 'varying float vPtSide; uniform float uPtFrameK;\nvoid main() {')
